import sys,random,json,subprocess,time
sys.path.insert(0,'/workspace')
from wire import *
random.seed(42)
# periodically valid-ish header with random payload and huge varints
vals=[0,1,2,3,63,64,16383,16384,(1<<30)-1,1<<30,(1<<40), (1<<60), (1<<62)-1]
def rv():
    x=random.choice(vals)
    w=random.choice([1,2,4,8])
    if x >= (1<<(8*w-2)):w=8
    return (([1,2,4,8].index(w)<<(8*w-2))|x).to_bytes(w,'big')
def randbody():
    typ=random.choice(list(range(0x20))+[0x30,0x31])
    b=bytearray([typ])
    if typ in [0x02,0x03]:
        for _ in range(random.randrange(0,8)):b+=rv()
    elif typ in [0x04]: b+=rv()*3
    elif typ in [0x05]: b+=rv()*2
    elif typ==0x06: b+=rv()+rv()+bytes(random.randrange(0,20))
    elif 0x08<=typ<=0x0f:
        b+=rv()
        if typ&4:b+=rv()
        if typ&2:
            n=random.randrange(0,20); b+=v(n)+bytes(random.randrange(0,20))
        else:b+=bytes(random.randrange(0,20))
    elif typ in [0x10,0x12,0x13,0x14,0x16,0x17]: b+=rv()
    elif typ in [0x11,0x15]:b+=rv()+rv()
    elif typ==0x18:
        l=random.choice([0,1,2,20,21,25]); b+=rv()+rv()+bytes([l])+bytes(random.randrange(l+3))+bytes(random.randrange(0,20))
    elif typ==0x19:b+=rv()
    elif typ in [0x1a,0x1b]:b+=bytes(random.randrange(0,12))
    elif typ==0x1c:b+=rv()+rv()+rv()+bytes(random.randrange(0,10))
    elif typ==0x1d:b+=rv()+rv()+bytes(random.randrange(0,10))
    elif typ==0x30:b+=bytes(random.randrange(0,20))
    elif typ==0x31:b+=rv()+bytes(random.randrange(0,20))
    return bytes(b)
traces=[]
for ti in range(64):
 ev=[]
 for j in range(random.randrange(0,80)):
  if random.random()<0.12: ev.append({'keys':random.sample(['I','H','A'],random.randrange(4))})
  else:
   # mostly valid headers with random payload, occasional malformed
   level=random.choice(['I','H','A','X'])
   payload=b''.join(randbody() for _ in range(random.randrange(0,5)))
   try:
    if level=='A': w=envelope('A',random.randrange(0,1000),payload,cid=random.choice([b'aa',b'bb']),phase=random.randrange(2),width=random.randrange(1,5))
    elif level in 'IH': w=envelope(level,random.randrange(0,1000),payload,width=random.randrange(1,5))
    else:w=bytes(random.randrange(256) for _ in range(random.randrange(0,30)))
   except Exception:
    w=bytes(random.randrange(256) for _ in range(random.randrange(0,30)))
   auth=[random.choice([None,0,1,2,3,10,(1<<62)-1]) for _ in range(random.randrange(0,6))]
   ev.append({'datagram':{'wire':w.hex(),'auth':auth}})
 traces.append({'limits':{'connection':random.choice([0,10,1000,(1<<62)-1]),'stream':random.choice([0,10,1000,(1<<62)-1]),'bidi':random.choice([0,4,16,1<<60]),'uni':random.choice([0,4,16,1<<60]),'cids':random.randrange(2,20)},
  'local':{'bidi':random.randrange(0,6),'uni':random.randrange(0,6),'cids':['aa','bb']},
  'peer':{'cid':'cc','token':'00'*16},'received':{k:random.choice([None,0,1,10,(1<<62)-1]) for k in ['I','H','A']},'events':ev})
inp=json.dumps({'traces':traces})
print('input',len(inp))
t=time.time();p=subprocess.run([sys.executable,'/workspace/run.py','/workspace/tmp/classes'],input=inp.encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=180);print('elapsed',time.time()-t,'rc',p.returncode,'out',len(p.stdout),'err',p.stderr.decode()[:3000])
if p.returncode==0:
 try:o=json.loads(p.stdout);print('ok traces',len(o['traces']),'packets',sum(len(x['packets']) for x in o['traces']))
 except Exception as e:print('jsonerr',e)
